# frozen_string_literal: true

require "digest"

module Cct
  module Seed
    # Attaches the branded, text-free banner images (db/seeds/cct/images, generated by
    # script/images/generate_seed_images.py) to the organization, homepage hero,
    # process group and every seeded process (by IDP theme). Idempotent: an image is
    # only (re)attached when missing or when the file's checksum changed.
    #
    # Abstract OCL-palette art only — no photos and no City of Cape Town marks (plan KTD10).
    class Images
      DIR = Rails.root.join("db/seeds/cct/images")
      WARD_ALLOCATIONS_SLUG = "ward-allocations-2026-27"

      def initialize(organization:, data:, logger: Rails.logger)
        @organization = organization
        @data = data
        @logger = logger
        @changed = 0
      end

      def call
        attach!(organization, :logo, "logo.png")
        attach!(organization, :favicon, "favicon.png")
        homepage_hero!
        group = Decidim::ParticipatoryProcessGroup.where(organization:)
                                                  .find { |g| g.title.to_h["en"].to_s.start_with?("Have your say") }
        attach!(group, :hero_image, "group-have-your-say.png") if group

        data.items.each do |item|
          process = Decidim::ParticipatoryProcess.find_by(organization:, slug: item.slug)
          next unless process

          attach!(process, :hero_image, theme_file(item.theme_key))
        end

        allocations = Decidim::ParticipatoryProcess.find_by(organization:, slug: WARD_ALLOCATIONS_SLUG)
        attach!(allocations, :hero_image, "ward-allocations.png") if allocations

        logger.info("[cct:seed:images] #{@changed} image(s) attached or updated")
        @changed
      end

      private

      attr_reader :organization, :data, :logger

      def theme_file(key)
        file = "theme-#{key}.png"
        DIR.join(file).exist? ? file : "group-have-your-say.png"
      end

      def homepage_hero!
        block = Decidim::ContentBlock.find_by(organization:, scope_name: "homepage", manifest_name: "hero")
        return logger.warn("[cct:seed:images] no homepage hero content block; skipped") unless block

        attachment = block.attachments.find_or_initialize_by(name: "background_image")
        attachment.save! if attachment.new_record?
        attach!(attachment, :file, "home-hero.png")
      end

      def attach!(record, name, file)
        path = DIR.join(file)
        raise Error, "missing seed image #{path}" unless path.exist?

        attached = record.public_send(name)
        checksum = Digest::MD5.file(path).base64digest
        return if attached.attached? && attached.blob.checksum == checksum

        attached.attach(io: File.open(path, "rb"), filename: file, content_type: "image/png")
        record.save!(validate: false) if record.changed?
        @changed += 1
      end
    end
  end
end
